      "note": "Chả Bò Bà Quýt does proper street-side beef patties, grilled smoky and wrapped with herbs. Ngon quá (so tasty)."
    },
    {
      "poi_id": "p251",
      "kind": "activity",
      "must_do_id": null,
      "note": "Han River Bridge glows quietly over the water, a gentle evening stroll with the city lights doing all the talking."
    },
    {
      "poi_id": "p258",
      "kind": "activity",
      "must_do_id": null,
      "note": "Dragon Bridge after dark is pure theatre: the big fella lights up and the riverside buzzes with locals out for a wander."
    }
  ]
}
